    /** @return array{0:float,1:float,2:float} */ private function hexRgb(string $hex): array {$hex=ltrim($hex,'#');return [hexdec(substr($hex,0,2))/255,hexdec(substr($hex,2,2))/255,hexdec(substr($hex,4,2))/255];}
